  --button-background-hover: #1849a8;
  --button-text: #ffffff;
  --chip-background: #e8eef9;
  --chip-text: #1b2433;
  --field-border: #7d8799;
  --field-border-error: #c4231b;
  --gap-s: 4px;
  --padding-xs: 4px;
  --padding-s: 8px;
  --padding-m: 12px;
