import { useState } from 'react';

export default function Chip({ Size = 'M', Icon = false, Label = 'Filter' }) {
  const [pressed, setPressedState] = useState(false);

  const classNames = ['chip'];
  if (Size === 'L') {
    classNames.push('chip--l');
  }

  return (
    <button
      type="button"
      className={classNames.join(' ')}
      aria-pressed={pressed}
      onClick={() => setPressedState(!pressed)}
    >
      {Icon && Size === 'L' && (
        <svg
          width="12"
          height="12"
          viewBox="0 0 12 12"
          fill="currentColor"
          style={{ flexShrink: 0 }}
        >
          <circle cx="6" cy="6" r="6" />
        </svg>
      )}
      {Label}
    </button>
  );
}

