/* Tag component */
.tag {
  box-sizing: border-box;
  height: 20px;
  padding: var(--padding-xs) var(--padding-s);
  border-radius: var(--radii-chip);
  background-color: var(--chip-background);
  color: var(--chip-text);
  font-family: Inter;
  font-size: 12px;
  font-weight: 500;
  line-height: 16px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.tag--positive {
  background-color: #d6f5e3;
  color: #136c3a;
}

@media (prefers-color-scheme: dark) {
  .tag--positive {
    background-color: #d6f5e3;
    color: #136c3a;
  }
}

