files.src/components/Tag.jsx:
export default function Tag({ className, Label = "New", Tone = "Neutral" }) {
  const tagClass = Tone === "Positive" ? "tag tag--positive" : "tag";
  const finalClass = className ? `${tagClass} ${className}` : tagClass;

  return (
    <div className={finalClass}>
      {Label}
    </div>
  );
}

