export default function Tag({ className, Label = "New", Tone = "Neutral" }) {
  const classes = [
    "tag",
    Tone === "Positive" && "tag--positive",
    className
  ].filter(Boolean).join(" ");

  return (
    <div className={classes}>
      {Label}
    </div>
  );
}

